import XCTest

/// FinalGate evidence tour: navigates ThreadGrid surfaces on Simulator and
/// captures named screenshots as XCTAttachments. Product repo untouched.
final class ScreenshotTour: XCTestCase {
    override func setUpWithError() throws { continueAfterFailure = true }

    @MainActor
    private func shot(_ name: String) {
        let s = XCUIScreen.main.screenshot()
        let a = XCTAttachment(screenshot: s)
        a.name = name
        a.lifetime = .keepAlways
        add(a)
    }

    @MainActor
    private func backToRoot(_ app: XCUIApplication) {
        let back = app.navigationBars.buttons.firstMatch
        if back.waitForExistence(timeout: 1) { back.tap() }
    }

    @MainActor
    func testSurfaceTour() throws {
        let app = XCUIApplication(bundleIdentifier: "com.threadgrid.atelier")
        app.launchArguments = ["-syntheticCapture"]
        app.launch()
        sleep(3)
        shot("tour-01-charts-empty")

        // --- Create via camera seam ---
        let emptyCTA = app.buttons["Create your first chart"]
        if emptyCTA.waitForExistence(timeout: 4) { emptyCTA.tap() }
        else { app.tabBars.buttons["Create"].tap() }
        sleep(1)
        shot("tour-02-create-wizard")

        addUIInterruptionMonitor(withDescription: "Camera permission") { alert in
            for label in ["Allow", "OK", "Allow Full Access"] where alert.buttons[label].exists {
                alert.buttons[label].tap(); return true
            }
            return false
        }
        let takePhoto = app.buttons.matching(NSPredicate(format: "label BEGINSWITH 'Take a photo'")).firstMatch
        if takePhoto.waitForExistence(timeout: 6) {
            takePhoto.tap(); app.tap()
            let allow = app.alerts.buttons["Allow"]
            if allow.waitForExistence(timeout: 4) { allow.tap(); shot("tour-03-camera-permission") }
            let usePhoto = app.buttons["Use this photo"]
            if usePhoto.waitForExistence(timeout: 8) { shot("tour-04-synthetic-capture"); usePhoto.tap() }
            let cont = app.buttons["Looks good, continue"]
            if cont.waitForExistence(timeout: 15) { shot("tour-05-tuning-preview"); cont.tap() }
            let nameField = app.textFields["Chart name"]
            if nameField.waitForExistence(timeout: 5) {
                nameField.tap(); nameField.typeText("QA Fox")
                shot("tour-06-naming-keyboard")
                app.buttons["Save chart"].tap()
            }
        }
        let saved = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'QA Fox'")).firstMatch
        _ = saved.waitForExistence(timeout: 15)
        sleep(2)
        shot("tour-07-chart-detail-or-home")

        // --- Editor ---
        let edit = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Edit'")).firstMatch
        if edit.waitForExistence(timeout: 3) { edit.tap(); sleep(2); shot("tour-08-chart-editor"); backToRoot(app) }
        sleep(1)

        // --- Stitch session ---
        let stitch = app.buttons.matching(NSPredicate(format: "label CONTAINS 'stitching'")).firstMatch
        if stitch.waitForExistence(timeout: 3) {
            stitch.tap(); sleep(2); shot("tour-09-stitch-session")
            backToRoot(app)
        }
        sleep(1)

        // --- Export sheet ---
        let export = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Export'")).firstMatch
        if export.waitForExistence(timeout: 3) {
            export.tap(); sleep(2); shot("tour-10-chart-export")
            let card = app.buttons.matching(NSPredicate(format: "label CONTAINS 'Save Card' OR label CONTAINS 'Share'")).firstMatch
            if card.waitForExistence(timeout: 2) { shot("tour-11-export-actions") }
            app.swipeDown(); sleep(1)
        }

        // --- Back to Charts home (populated) ---
        app.tabBars.buttons["Charts"].tap(); sleep(1)
        backToRoot(app); sleep(1)
        shot("tour-12-charts-populated")

        // --- Threads tab ---
        app.tabBars.buttons["Threads"].tap(); sleep(2)
        shot("tour-13-threads")

        // --- Stitch tab root ---
        app.tabBars.buttons["Stitch"].tap(); sleep(1)
        shot("tour-14-stitch-tab")

        // --- Settings + Credit Shop ---
        app.tabBars.buttons["Charts"].tap(); sleep(1)
        let gear = app.buttons["Settings"]
        if gear.waitForExistence(timeout: 3) {
            gear.tap(); sleep(1); shot("tour-15-settings")
            let creditRow = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'credits'")).firstMatch
            if creditRow.waitForExistence(timeout: 3) { creditRow.tap(); sleep(2); shot("tour-16-credit-shop") }
        }
    }
}
